# Transcripción del catálogo: (página, caja, código, nombre, descripción)
# Sección por página en SECCION.
SECCION = {}
S = []

def pag(tag, seccion, *filas):
    SECCION[tag] = seccion
    for f in filas:
        S.append((tag,) + f)

